/* ---- cell descriptor constructors (native-int chain contract) ----
 * The config builds its banks from these. Each carries the `sens` of its
 * knob-response class (see the three classes at the top of this file), and
 * every discrete kind CLAMPS at its ends rather than wrapping — an accidental
 * extra detent shouldn't flip On back to Off. All read KIT_PARAM_MAX and the
 * sens tunables at CALL time, so a config that reassigns them must do so
 * BEFORE building its banks. */

const kToggleLabels = ["Off", "On"];

/* Continuous 0..KIT_PARAM_MAX, rendered as an arc knob. */
function uni(key, label) { return { key, label, kind: "unipolar", min: 0, max: KIT_PARAM_MAX, step: 1, sens: KIT_SENS }; }
/* Center-detent continuous (pan, tune): arc knob with a 12-o'clock tick;
 * value shows signed offset from center; center-out bar semantics. */
function bip(key, label) { return { key, label, kind: "bipolar", min: 0, max: KIT_PARAM_MAX, step: 1, sens: KIT_SENS, dflt: Math.round(KIT_PARAM_MAX / 2) }; }
/* On/Off toggle, rendered as a movy horizontal bar. */
function tog(key, label) { return { key, label, kind: "enum", min: 0, max: 1, step: 1, sens: KIT_DELIB_SENS, options: kToggleLabels }; }
/* Multi-option enum, rendered as a framed square + a scrolling list overlay
 * while touched. `sq` (optional): per-option single-line square labels. */
function enumc(key, label, options, sq) { return { key, label, kind: "enum", min: 0, max: options.length - 1, step: 1, sens: options.length <= 2 ? KIT_DELIB_SENS : KIT_PICK_SENS, options, sq }; }
/* Small signed range (+N display), rendered as a value square. */
function oct(key, label, lo, hi) { return { key, label, kind: "octave", min: lo, max: hi, step: 1, sens: KIT_PICK_SENS }; }
/* Small positive count, rendered as a value square. */
function count(key, label, lo, hi) { return { key, label, kind: "count", min: lo, max: hi, step: 1, sens: KIT_PICK_SENS }; }
/* Envelope-stage cell (use on `env: true` banks, cells 0-3 = A/D/S/R drive
 * the full-width envelope graphic; other fader cells render as a vbar). */
function fader(key, label) { return { key, label, kind: "fader", min: 0, max: KIT_PARAM_MAX, step: 1, sens: KIT_SENS }; }
/* Modulation-target slot that is currently NONE — a framed box with a drawn
 * diagonal cross (movy's xbox). Reads as "nothing routed here" at a glance;
 * use in place of an enum whose unset state deserves more than a "--". */
function xbox(key, label, options) { return { key, label, kind: "xbox", min: 0, max: (options ? options.length - 1 : 1), step: 1, sens: KIT_PICK_SENS, options: options || kToggleLabels }; }
/* Musical length drawn as a real stacked FRACTION in a framed square
 * (numerator / 1px rule / denominator, movy's length square). The alternative
 * to a big read-out for "1/16"-style values — pick whichever suits the param. */
function len(key, label, options) { return { key, label, kind: "len", min: 0, max: options.length - 1, step: 1, sens: KIT_PICK_SENS, options }; }
/* One-shot or RELATIVE control (davebox): the square shows "< >" at rest —
 * "turn either way" — and swaps to the live value while its knob is touched.
 * `oneWay: true` (destructive actions) keeps "< >" even when touched. */
function action(key, label, options, oneWay) { return { key, label, kind: "action", min: 0, max: (options ? options.length - 1 : 1), step: 1, sens: KIT_DELIB_SENS, options: options || kToggleLabels, oneWay: !!oneWay }; }
/* Playback direction as real arrows (davebox): 0 Fwd, 1 Bwd, 2 ping-pong out,
 * 3 ping-pong in. `options` supply the picker/label names. */
function dir(key, label, options) { return { key, label, kind: "dir", min: 0, max: 3, step: 1, sens: KIT_PICK_SENS, options: options || ["Fwd", "Bwd", "PPf", "PPb"] }; }
